def singleNumber(nums):
    unique = 0
    for num in nums:
        unique ^= num
    return unique

def count_extensions(files):
    ext_count = {}
    for file in files:
        ext = file.split('.')[-1]
        ext_count[ext] = ext_count.get(ext, 0) + 1
    return ext_count

class MessageQueue:
    def __init__(self):
        self.queue = []

    def send(self, message):
        self.queue.append(message)

    def receive(self):
        return self.queue.pop(0) if self.queue else None
